<script setup lang="ts">import type {Journey} from '../types';import AppIcon from './AppIcon.vue';defineProps<{journey:Journey}>();const modeLabel={WALK:'Caminhada aproximada',TRANSIT:'Ônibus demonstrativo',TRANSFER:'Baldeação'};</script>
<template><section class="detail" aria-labelledby="detail-title"><header><div><h2 id="detail-title">Detalhes do trajeto</h2><p>Horários programados no cenário sintético</p></div><div class="duration"><strong>{{ journey.durationMinutes }} min</strong><span>{{ journey.departure }} → {{ journey.arrival }}</span></div></header><ol class="timeline"><li v-for="(leg,index) in journey.legs" :key="index" :class="leg.mode.toLowerCase()"><div class="time">{{ leg.departure }}<br><small>{{ leg.arrival }}</small></div><div class="node"><AppIcon :name="leg.mode==='TRANSIT'?'bus':leg.mode==='WALK'?'walk':'swap'" /></div><div class="step"><strong>{{ leg.line ? `${leg.line} · ${leg.direction}` : modeLabel[leg.mode] }}</strong><span>{{ leg.from }} → {{ leg.to }}</span><small>{{ leg.provenance }}</small></div></li></ol></section></template>
